#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void)  {
    int n, m;
    char grid[40][41];
    // 保存原网格；后续统计不能改写它，否则邻居状态会被污染。
    scanf("%d%d", &n, &m);
    for (int row = 0; row < n; ++row)  {
        scanf("%40s", grid[row]);
    }
    for (int row = 0; row < n; ++row)  {
        for (int col = 0; col < m; ++col)  {
            if (grid[row][col] == '#')  {
                putchar('#');
                continue;
            }
            int count = 0;
            // 九个偏移组合排除 (0,0)，只留下八个方向的邻居。
            for (int dr = -1; dr <= 1; ++dr)  {
                for (int dc = -1; dc <= 1; ++dc)  {
                    int r = row + dr, c = col + dc;
                    if ((dr != 0 || dc != 0) && r >= 0 && r < n && c >= 0 && c < m &&
                    grid[r][c] == '#')  {
                        ++count;
                    }
                }
            }
            // 计数范围 0..8，所以每个空位输出恰好一个数字字符。
            putchar('0' + count);
        }
        putchar('\n');
    }
    return 0;
}

