use std::io:: {
    self, Read
}
;
fn main()  {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    // 保存原网格；后续统计不能改写它，否则邻居状态会被污染。
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let m: usize = tokens.next().unwrap().parse().unwrap();
    let grid: Vec<&[u8]> = tokens.map(|row| row.as_bytes()).collect();
    let mut answer = String::new();
    for row in 0..n  {
        for col in 0..m  {
            if grid[row][col] == b'#'  {
                answer.push('#');
                continue;
            }
            let mut count = 0u8;
            // 九个偏移组合排除 (0,0)，只留下八个方向的邻居。
            for dr in -1i32..=1  {
                for dc in -1i32..=1  {
                    let r = row as i32 + dr;
                    let c = col as i32 + dc;
                    if (dr != 0 || dc != 0)
                    && r >= 0
                    && r < n as i32
                    && c >= 0
                    && c < m as i32
                    && grid[r as usize][c as usize] == b'#'
                    {
                        count += 1;
                    }
                }
            }
            // 计数范围 0..8，所以每个空位输出恰好一个数字字符。
            answer.push((b'0' + count) as char);
        }
        answer.push('\n');
    }
    print!("{}", answer);
}
